  FaClock,
  FaLink,
} from "react-icons/fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      city: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",

      states: [],
      cities: [],
      deviceTypes: [],
      deviceBrands: [],

      loadingData: true,
      loadingCities: false,
      submitting: false,

      message: "",
      error: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
    this.loadData = this.loadData.bind(this);
    this.loadCities = this.loadCities.bind(this);
  }

  componentDidMount() {
    this.loadData();
  }

  getToken() {
    return localStorage.getItem("token");
  }

  async loadData() {
    try {
      this.setState({
        loadingData: true,
        error: "",
      });

      const token = this.getToken();

      const [citiesResponse, typesResponse] = await Promise.all([
        fetch("https://iranaserviceapp.ir/test/api/cities", {
          method: "GET",
          headers: {
            Accept: "application/json",
            ...(token
              ? {
                  Authorization: `Bearer ${token}`,
                }
              : {}),
          },
        }),

        fetch("https://iranaserviceapp.ir/test/api/list-type", {
          method: "GET",
          headers: {
            Accept: "application/json",
            ...(token
              ? {
                  Authorization: `Bearer ${token}`,
                }
              : {}),
          },
        }),
      ]);

      const citiesData = await citiesResponse.json();
      const typesData = await typesResponse.json();

      this.setState({
        states: citiesData.states || [],
        deviceTypes: typesData.types || [],
        deviceBrands: typesData.brands || [],
        loadingData: false,
      });
    } catch (error) {
      console.error("Load data error:", error);

      this.setState({
        loadingData: false,
        error: "خطا در دریافت اطلاعات فرم",
      });
    }
  }

  async loadCities(stateId) {
    if (!stateId) {
      this.setState({
        cities: [],
        city: "",
      });

      return;
    }

    try {
      this.setState({
        loadingCities: true,
        cities: [],
        city: "",
      });

      const token = this.getToken();

      const response = await fetch(
        `https://iranaserviceapp.ir/test/api/cities?id=${stateId}`,
        {
          method: "GET",
          headers: {
            Accept: "application/json",
            ...(token
              ? {
                  Authorization: `Bearer ${token}`,
                }
              : {}),
          },
        }
      );

      const data = await response.json();

      this.setState({
        cities: data.cities || [],
        loadingCities: false,
      });
    } catch (error) {
      console.error("Load cities error:", error);

      this.setState({
        cities: [],
        loadingCities: false,
        error: "خطا در دریافت شهرها",
      });
    }
  }

  handleChange(field) {
    return (e) => {
      const value = e.target.value;

      this.setState(
        {
          [field]: value,
          ...(field === "province"
            ? {
                city: "",
              }
            : {}),
        },
        () => {
          if (field === "province") {
            this.loadCities(value);
          }
        }
      );
    };
  }

  async handleSubmit(e) {
    e.preventDefault();

    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    this.setState({
      message: "",
      error: "",
    });

    if (!fullName.trim()) {
      this.setState({
        error: "نام کامل را وارد کنید.",
      });
      return;
    }

    if (!mobile.trim()) {
      this.setState({
        error: "شماره موبایل را وارد کنید.",
      });
      return;
    }

    if (!province) {
      this.setState({
        error: "استان را انتخاب کنید.",
      });
      return;
    }

    if (!city) {
      this.setState({
        error: "شهر را انتخاب کنید.",
      });
      return;
    }

    if (!deviceType) {
      this.setState({
        error: "نوع دستگاه را انتخاب کنید.",
      });
      return;
    }

    if (!deviceBrand) {
      this.setState({
        error: "برند دستگاه را انتخاب کنید.",
      });
      return;
    }

    if (!deviceIssue.trim()) {
      this.setState({
        error: "ایراد دستگاه را وارد کنید.",
      });
      return;
    }

    try {
      this.setState({
        submitting: true,
      });

      const token = this.getToken();

      let user = null;

      try {
        const savedUser = localStorage.getItem("user");

        if (savedUser) {
          user = JSON.parse(savedUser);
        }
      } catch (error) {
        console.error("User parse error:", error);
      }

      /*
       * فیلدهای ارسالی دقیقاً مطابق create در Laravel هستند.
       *
       * fullName    -> name
       * mobile      -> mobile
       * landline    -> mobile2
       * province    -> state
       * city        -> city
       * deviceBrand -> device_brand
       * deviceType  -> device_type
       * deviceIssue -> problem
       * visitTime   -> time
       * description -> description
       */

      const requestData = {
        name: fullName,
        mobile: mobile,
        mobile2: landline,
        state: province,
        city: city,
        device_brand: deviceBrand,
        device_type: deviceType,
        address: address,
        problem: deviceIssue,
        description: description,
        time: visitTime,
      };

      /*
       * create در Laravel از code استفاده می‌کند.
       * اگر code در اطلاعات کاربر وجود داشته باشد، ارسال می‌شود.
       */
      if (user && user.code) {
        requestData.code = user.code;
      }

      console.log("Data sent to API:", requestData);

      const response = await fetch(
        "https://iranaserviceapp.ir/test/api/create",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
            ...(token
              ? {
                  Authorization: `Bearer ${token}`,
                }
              : {}),
          },
          body: JSON.stringify(requestData),
        }
      );

      const data = await response.json();

      console.log("Create response:", data);

      if (response.ok && data.status === "1") {
        this.setState({
          message: data.message || "درخواست با موفقیت ثبت شد.",
          error: "",
          fullName: "",
          mobile: "",
          landline: "",
          province: "",
          city: "",
          address: "",
          deviceType: "",
          deviceBrand: "",
          deviceIssue: "",
          visitTime: "",
          description: "",
          cities: [],
          submitting: false,
        });
      } else {
        this.setState({
          submitting: false,
          error: data.message || "ثبت درخواست انجام نشد.",
        });
      }
    } catch (error) {
      console.error("Create request error:", error);

      this.setState({
        submitting: false,
        error: "خطا در ارتباط با سرور.",
      });
    }
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
      states,
      cities,
      deviceTypes,
      deviceBrands,
      loadingData,
      loadingCities,
      submitting,
      message,
      error,
    } = this.state;

    return (
      <div className="container pt-3">
        <div
          className="mx-auto"
          style={{
            maxWidth: "480px",
          }}
        >
          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          {loadingData && (
            <div className="text-center mb-3">
              <small className="text-muted">
                در حال دریافت اطلاعات...
              </small>
            </div>
          )}

          {error && (
            <div
              className="alert alert-danger text-center py-2"
              style={{
                fontSize: "13px",
                borderRadius: "12px",
              }}
            >
              {error}
            </div>
          )}

          {message && (
            <div
              className="alert alert-success text-center py-2"
              style={{
                fontSize: "13px",
                borderRadius: "12px",
              }}
            >
              {message}
            </div>
          )}

          <form onSubmit={this.handleSubmit}>
            {/* نام کامل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaUser />
              </div>

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
              />
            </div>

            {/* شماره موبایل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
              />
            </div>

            {/* تلفن ثابت */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
              />
            </div>

            {/* استان */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={province}
                onChange={this.handleChange("province")}
                disabled={loadingData}
              >
                <option value="" disabled>
                  استان
                </option>

                {states.map((state) => (
                  <option key={state.id} value={state.id}>
                    {state.name}
                  </option>
                ))}
              </select>
            </div>

            {/* شهر */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={city}
                onChange={this.handleChange("city")}
                disabled={!province || loadingCities}
              >
                <option value="" disabled>
                  {loadingCities ? "در حال دریافت شهرها..." : "شهر"}
                </option>

                {cities.map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.name}
                  </option>
                ))}
              </select>
            </div>

            {/* آدرس */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
              />
            </div>

            {/* نوع دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaImage />
              </div>

              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                disabled={loadingData}
              >
                <option value="" disabled>
                  نوع دستگاه
                </option>

                {deviceTypes.map((type) => (
                  <option key={type.id} value={type.id}>
                    {type.name}
                  </option>
                ))}
              </select>
            </div>

            {/* برند دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaTag />
              </div>

              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                disabled={loadingData}
              >
                <option value="" disabled>
                  برند دستگاه
                </option>

                {deviceBrands.map((brand) => (
                  <option key={brand.id} value={brand.id}>
                    {brand.name}
                  </option>
                ))}
              </select>
            </div>

            {/* ایراد دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaQuestionCircle />
              </div>

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
              />
            </div>

            {/* زمان مراجعه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaClock />
              </div>

              <input
                type="text"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
              />
            </div>

            {/* توضیحات */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaLink />
              </div>

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
              />
            </div>

            {/* دکمه */}
            <button
              type="submit"
              className="btn btn-sub w-100 fw-bold py-2 rounded-4"
              disabled={loadingData || submitting}
            >
              <small>
                {submitting ? "در حال ثبت..." : "ثبت درخواست"}
              </small>
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
